#!/usr/bin/env bash
#
# Extract trajectory metrics from TrackMate-compatible or ABCA XML files.
#
# Usage:
#   ./extract_trajectory_metrics.sh CONFIG_FILE
#
# The Python interpreter is read from python.conf, generated by
# setup_python.sh. Analysis parameters are read from CONFIG_FILE.
#

set -Eeuo pipefail

cd "$(dirname "$0")"

die() {
    printf 'Error: %s\n' "$*" >&2
    exit 1
}

usage() {
    cat <<EOF_USAGE
Usage:
  $(basename "$0") CONFIG_FILE

CONFIG_FILE is a trusted Bash configuration file containing the input/output
paths and trajectory-analysis parameters.
EOF_USAGE
}

if (( $# != 1 )); then
    usage >&2
    exit 1
fi

case "$1" in
    -h|--help)
        usage
        exit 0
        ;;
esac

PYTHON_CONFIG="../../setup/python.conf"
ANALYSIS_CONFIG="$1"
PYTHON_SCRIPT="extract_trajectory_metrics.py"

[[ -f "$PYTHON_CONFIG" ]] \
    || die "Python configuration file not found: $PYTHON_CONFIG"

[[ -f "$ANALYSIS_CONFIG" ]] \
    || die "Analysis configuration file not found: $ANALYSIS_CONFIG"

[[ -f "$PYTHON_SCRIPT" ]] \
    || die "Python script not found: $PYTHON_SCRIPT"

# shellcheck disable=SC1090
source "$PYTHON_CONFIG"

# shellcheck disable=SC1090
source "$ANALYSIS_CONFIG"

: "${PYTHON:?PYTHON is not defined in $PYTHON_CONFIG}"
: "${XML_SOURCE:?XML_SOURCE is not defined in $ANALYSIS_CONFIG}"
: "${OUTPUT_DIR:?OUTPUT_DIR is not defined in $ANALYSIS_CONFIG}"

[[ -x "$PYTHON" ]] \
    || die "Python interpreter is not executable: $PYTHON"

[[ -e "$XML_SOURCE" ]] \
    || die "XML source not found: $XML_SOURCE"

FRAME_INTERVAL_S="${FRAME_INTERVAL_S:-0.22}"
COORD_SCALE="${COORD_SCALE:-1}"
SPATIAL_UNIT="${SPATIAL_UNIT:-micron}"
MIN_SPOTS="${MIN_SPOTS:-10}"
DIRECTION_THRESHOLD_DEG="${DIRECTION_THRESHOLD_DEG:-30}"
MAX_LAG="${MAX_LAG:-25}"

LENGTH_FILTER_MODE="${LENGTH_FILTER_MODE:-percentile}"
LENGTH_FILTER_PERCENTILE="${LENGTH_FILTER_PERCENTILE:-90}"
LENGTH_FILTER_MAX_POINTS="${LENGTH_FILTER_MAX_POINTS:-0}"
FILTERED_SUBDIR="${FILTERED_SUBDIR:-length_filtered}"

filter_args=()

case "$LENGTH_FILTER_MODE" in
    percentile)
        filter_args=(
            --length-filter-percentile "$LENGTH_FILTER_PERCENTILE"
            --filtered-subdir "$FILTERED_SUBDIR"
        )
        ;;

    max_points)
        filter_args=(
            --length-filter-max-points "$LENGTH_FILTER_MAX_POINTS"
            --filtered-subdir "$FILTERED_SUBDIR"
        )
        ;;

    none)
        filter_args=(--no-length-filter)
        ;;

    *)
        die "Invalid LENGTH_FILTER_MODE: $LENGTH_FILTER_MODE"
        ;;
esac

mkdir -p "$OUTPUT_DIR"

echo "Extracting trajectory metrics..."
echo "  XML source: $XML_SOURCE"
echo "  Output:     $OUTPUT_DIR"
echo "  Python:     $PYTHON"

"$PYTHON" "$PYTHON_SCRIPT" \
    "$XML_SOURCE" \
    --outdir "$OUTPUT_DIR" \
    --dt "$FRAME_INTERVAL_S" \
    --coord-scale "$COORD_SCALE" \
    --unit "$SPATIAL_UNIT" \
    --min-spots "$MIN_SPOTS" \
    --direction-threshold-deg "$DIRECTION_THRESHOLD_DEG" \
    --max-lag "$MAX_LAG" \
    "${filter_args[@]}"

echo "Trajectory metric extraction completed."
